import { action } from "solid-js";

export const runStep = (cb) => {
  void action(function* () {
    cb();
  })();
};
export const step = (strings) => {
  runStep(() => {});
  return strings.join("");
};
export class Stepper {
  constructor() {
    runStep(() => {});
  }
}
export const StepView = () => {
  runStep(() => {});
  return null;
};
export const reset = () => {
  runStep(() => {});
};
